-- 3. Add Biking activity to existing Ohio & Erie Canal Towpath Trail
UPDATE pois
SET primary_activities = 'Biking, Hiking'
WHERE name = 'Ohio & Erie Canal Towpath Trail'
  AND (primary_activities IS NULL OR primary_activities = '');

-- 4. Add Biking activity to existing Cleveland Lakefront Bikeway (in case 073 already ran without it)
UPDATE pois
SET primary_activities = 'Biking, Hiking'
WHERE name = 'Cleveland Lakefront Bikeway'
  AND (primary_activities IS NULL OR primary_activities = '');

